import boto3
import os
from typing import Dict, Any, List

def extract_receipt_data(file_path: str) -> Dict[str, Any]:
    """
    Extracts structured data from a receipt file using Amazon Textract.

    :param file_path: Path to the local receipt image file.
    :return: A dictionary containing the extracted receipt data.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file was not found: {file_path}")

    textract_client = boto3.client(
        "textract",
        # Credentials and region are typically configured via environment variables
        # (AWS_ACCESS_KEY_ID, AWS_SECRET_ACCESS_KEY, AWS_REGION) or an IAM role.
    )

    with open(file_path, "rb") as document:
        image_bytes = document.read()

    response = textract_client.analyze_expense(
        Document={'Bytes': image_bytes}
    )

    extracted_data = {
        "merchant": None,
        "tax": None,
        "total": None,
        "items": []
    }

    if not response.get("ExpenseDocuments"):
        return extracted_data

    # Assuming one receipt per image
    doc = response["ExpenseDocuments"][0]

    # Extract summary fields
    for field in doc.get("SummaryFields", []):
        field_type = field.get("Type", {}).get("Text")
        value = field.get("ValueDetection", {}).get("Text")
        if not value:
            continue

        if field_type == "VENDOR_NAME":
            extracted_data["merchant"] = value
        elif field_type == "TOTAL":
            try:
                # Basic cleaning for float conversion
                cleaned_value = value.replace("$", "").replace(",", "")
                extracted_data["total"] = float(cleaned_value)
            except (ValueError, TypeError):
                extracted_data["total"] = value # Keep as string if conversion fails
        elif field_type == "TAX":
            try:
                cleaned_value = value.replace("$", "").replace(",", "")
                extracted_data["tax"] = float(cleaned_value)
            except (ValueError, TypeError):
                extracted_data["tax"] = value


    # Extract line items
    for group in doc.get("LineItemGroups", []):
        for item in group.get("LineItems", []):
            line_item_data = {}
            for expense_field in item.get("LineItemExpenseFields", []):
                field_type = expense_field.get("Type", {}).get("Text")
                value = expense_field.get("ValueDetection", {}).get("Text")
                if not value:
                    continue

                if field_type == "ITEM":
                    line_item_data["description"] = value
                elif field_type == "PRICE":
                     try:
                        cleaned_value = value.replace("$", "").replace(",", "")
                        line_item_data["price"] = float(cleaned_value)
                     except (ValueError, TypeError):
                        line_item_data["price"] = value

            if line_item_data:
                 extracted_data["items"].append(line_item_data)

    return extracted_data
